const conv = $("Load Conversation").first().json;
const text = ($("Normalize Inbound").first().json.text || "").trim().toLowerCase();
const offered = (conv.offered_slots || "").split("|").filter(Boolean);
let slot = null;
if (/^1\b/.test(text) && offered[0]) { slot = offered[0]; }
else if (/^2\b/.test(text) && offered[1]) { slot = offered[1]; }
else { slot = offered.find(s => text.includes(s.toLowerCase())) || null; }
return [{ json: { matched: !!slot, slot_label: slot || "", phone: conv.phone } }];

const slots = $input.all().map(i => i.json).filter(r => r.slot_label);
const phone = $("Normalize Inbound").first().json.phone;
if (!slots.length) {
  return [{ json: { has_slots: false, phone } }];
}
const top = slots.slice(0, 2);
const lines = top.map((s, ix) => (ix + 1) + ") " + s.slot_label).join("   ");
return [{ json: {
  has_slots: true,
  phone,
  offered_slots: top.map(s => s.slot_label).join("|"),
  sms_text: "Great news - we have consult openings: " + lines + ". Reply 1 or 2 to grab one, or reply with a day that works better.",
  event: "offer_sent"
} }];

const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
const events = $input.all().map(i => i.json).filter(e => e.event && e.at && e.at >= cutoff);
const count = k => events.filter(e => e.event === k).length;
const missed = count("missed_call");
const textedBack = count("sms_sent") + count("sms_simulated");
const booked = count("booking_confirmed");
const queued = count("queued_for_callback") + count("cold_inbound") + count("inbound_logged");
const optOuts = count("opt_out");
const rows = [
  ["Missed calls caught", missed],
  ["Text-backs + replies sent", textedBack],
  ["Consults booked by text", booked],
  ["Handed to front desk", queued],
  ["Opt-outs", optOuts]
].map(r => "<tr><td style=\"padding:6px 14px 6px 0\">" + r[0] + "</td><td style=\"padding:6px 0;font-weight:bold\">" + r[1] + "</td></tr>").join("");
const html = "<div style=\"font-family:Arial,sans-serif;font-size:14px;color:#1a2332\">" +
  "<h2 style=\"margin:0 0 4px\">Practice digest - last 24 hours</h2>" +
  "<p style=\"margin:0 0 14px;color:#5d6b80\">Missed-call recovery mock. Every number below is traceable in ortho_events.</p>" +
  "<table style=\"border-collapse:collapse\">" + rows + "</table>" +
  "<p style=\"margin:14px 0 0;color:#5d6b80\">" + (booked > 0 ? "Every booking here started as a call nobody answered." : "No bookings in this window - queue and templates are ready.") + "</p></div>";
return [{ json: {
  subject: "Practice digest - " + missed + " missed calls caught, " + booked + " consults booked",
  html
} }];

const j = $input.first().json;
const b = j.body || j || {};
return [{ json: {
  phone: b.caller || b.From || b.from || '',
  call_id: b.call_id || b.CallSid || 'unknown'
} }];

const j = $input.first().json;
const b = j.body || j || {};
return [{ json: {
  phone: b.From || b.from || b.phone || '',
  text: b.Body || b.body || b.text || '',
  media_url: b.MediaUrl0 || b.media_url || '',
  num_media: parseInt(b.NumMedia || 0, 10) || 0
} }];

const t = ($('Normalize Inbound').first().json.text || '').trim();
const m = t.match(/^(?:text|send|msg)\s+(\+?[\d\-\s().]{8,})\s*[:\-]\s*(.+)$/i);
if (m) {
  const to = '+' + m[1].replace(/[^\d]/g, '');
  return [{ json: { mode: 'relay', to, message: m[2].trim() } }];
}
return [{ json: { mode: 'ask', question: t } }];

const q = $('Admin Command Parse').first().json.question || '';
const rows = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const facts = rows('Ctx Practice Facts').filter(r => r.key).map(r => (r.category ? ('[' + r.category + '] ') : '') + r.key + ': ' + r.value).join('
') || 'none';
const convs = rows('Ctx Conversations').filter(r => r.phone).slice(0, 15).map(r => r.phone + ' state=' + r.state + ' type=' + (r.patient_type || '-') + ' last="' + ((r.last_message || '').slice(0, 60)) + '" upd=' + (r.updated_at || '')).join('
') || 'none';
const queue = rows('Ctx Queue').filter(r => r.phone && r.status === 'open').slice(0, 15).map(r => r.phone + ' [' + r.reason + '] "' + ((r.context || '').slice(0, 70)) + '" ' + (r.created_at || '')).join('
') || 'empty';
const events = rows('Ctx Events').filter(r => r.event).slice(0, 30).map(r => (r.at || '') + ' ' + r.event + ' ' + (r.phone || '') + ' ' + ((r.detail || '').slice(0, 60))).join('
') || 'none';
const slots = rows('Ctx Slots').filter(r => r.slot_label).map(r => r.slot_label + ' ' + (r.taken ? ('TAKEN by ' + (r.booked_by || '?')) : 'open')).join('
') || 'none';
const prompt = 'You are the admin assistant for this practice, replying to the practice owner by SMS. Answer using ONLY the data below. Be specific and brief (under 450 characters), plain text, no markdown. If the data cannot answer, say so and name what is missing. Never invent patients, numbers, fees, or events.

OWNER QUESTION: ' + q + '

PRACTICE FACTS (identity, hours, insurance, fees, policies):
' + facts + '

OPEN CALLBACK QUEUE:
' + queue + '

CONVERSATIONS:
' + convs + '

RECENT EVENTS (newest first):
' + events + '

CONSULT SLOTS:
' + slots;
return [{ json: { question: q, prompt } }];

const q = ($('Normalize Inbound').first().json.text || '').toLowerCase();
const phone = $('Normalize Inbound').first().json.phone;
const facts = {};
for (const r of $('FAQ Facts').all().map(i => i.json)) { if (r.key) facts[r.key] = r.value; }
const rules = [
  { re: /insur|delta|metlife|cigna|aetna|humana|concordia|coverage|network/, a: () => 'We accept ' + (facts.accepted_plans || 'most major PPO plans') + '. ' + (facts.out_of_network || '') },
  { re: /invisalign|aligner/, a: () => 'Invisalign at our office runs ' + (facts.invisalign_range || '') + '. ' + (facts.financing || '') },
  { re: /price|cost|how much|fee|afford|financ|payment plan/, a: () => 'Braces run ' + (facts.braces_range || '') + ' and Invisalign ' + (facts.invisalign_range || '') + '. ' + (facts.financing || '') },
  { re: /hour|open|close|what time/, a: () => 'We are open Mon-Thu ' + (facts.monday_thursday || '') + ' and Fri ' + (facts.friday || '') + '. ' + (facts.weekend || '') },
  { re: /where|address|located|location|parking/, a: () => 'We are at ' + (facts.address || '') + '. ' + (facts.parking || '') },
  { re: /consult|first visit|x.?ray|exam/, a: () => 'New-patient consults are ' + (facts.new_patient_consult || 'free') + ' and take about ' + (facts.consult_length || '40 minutes') + '.' }
];
for (const r of rules) {
  if (r.re.test(q)) {
    const ans = (r.a() + ' Want to set up a consult? Just reply and we will grab you a time.').replace(/\s+/g, ' ').trim();
    return [{ json: { matched: true, phone, sms_text: ans, event: 'faq_answer' } }];
  }
}
return [{ json: { matched: false, phone } }];

const t = ($('Normalize Inbound').first().json.text || '').toLowerCase();
const cancel = /\b(cancel|can.?t make|cannot make|not coming|call it off)\b/.test(t);
return [{ json: { cancel, phone: $('Normalize Inbound').first().json.phone } }];

const slots = $('Get Booked Slots').all().map(i => i.json).filter(r => r.taken && r.booked_by && r.slot_label);
const sent = new Set($('Get Reminder Events').all().map(i => i.json.detail).filter(Boolean));
const dayIdx = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7 };
const out = [];
for (const s of slots) {
  const m = (s.slot_label || '').match(/^(\w{3})\s+(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) continue;
  const wd = dayIdx[m[1].toLowerCase()];
  if (!wd) continue;
  let h = (+m[2]) % 12;
  if (m[4].toUpperCase() === 'PM') h += 12;
  const min = +m[3];
  const dd = (wd - $now.weekday + 7) % 7;
  const t = $now.startOf('day').plus({ days: dd }).set({ hour: h, minute: min });
  const hrs = t.diff($now, 'hours').hours;
  if (hrs < 0) continue;
  const mk = (tag, msg) => {
    const key = s.slot_label + ':' + tag;
    if (!sent.has(key)) out.push({ json: { phone: s.booked_by, sms_text: msg, event: 'reminder_sent', detail: key } });
  };
  if (hrs >= 20 && hrs <= 28) mk('24h', 'Reminder from Harborline Orthodontics: your consult is tomorrow at ' + s.slot_label + '. Reply here if anything changes.');
  if (hrs >= 1 && hrs <= 3) mk('2h', 'See you soon! Your consult at Harborline Orthodontics is today at ' + s.slot_label + '. Free parking behind the building.');
}
return out;

const convs = $('Get Offered Convs').all().map(i => i.json).filter(r => r.phone && r.state === 'offered');
const nudged = new Set($('Get Nudge Events').all().map(i => i.json.phone).filter(Boolean));
const out = [];
for (const c of convs) {
  const upd = c.updated_at ? new Date(c.updated_at) : null;
  if (!upd || isNaN(upd.getTime())) continue;
  const ageH = ($now.toMillis() - upd.getTime()) / 3.6e6;
  if (ageH >= 24 && nudged.has(c.phone)) {
    out.push({ json: { action: 'expire', phone: c.phone, last: c.last_message || '' } });
  } else if (ageH >= 4 && !nudged.has(c.phone)) {
    out.push({ json: { action: 'nudge', phone: c.phone, sms_text: 'Still want to grab one of those consult times at Harborline Orthodontics? Reply 1 or 2 and it is yours - or reply with a day that works better.', event: 'nudge_sent' } });
  }
}
return out;

const j = $input.first().json;
const b = j.body || j || {};
return [{ json: {
  phone: b.phone || b.From || '',
  ref: b.submission_id || b.ref || 'form'
} }];

const j = $input.first().json;
const b = j.body || j || {};
return [{ json: {
  phone: b.phone || b.From || '',
  amount: String(b.amount || ''),
  ref: b.reference || b.ref || 'payment'
} }];

const pending = $('Get Pending Forms').all().map(i => i.json).filter(r => r.phone && r.status === 'pending');
const reminded = new Set($('Get Form Reminder Events').all().map(i => i.json.phone).filter(Boolean));
const out = [];
for (const f of pending) {
  const sent = f.sent_at ? new Date(f.sent_at) : null;
  if (!sent || isNaN(sent.getTime())) continue;
  const ageH = ($now.toMillis() - sent.getTime()) / 3.6e6;
  if (ageH >= 20 && !reminded.has(f.phone)) {
    out.push({ json: { phone: f.phone, sms_text: 'Quick reminder from Harborline Orthodontics - your new-patient forms take 5 minutes and save you time at your visit: ' + (f.form_link || ''), event: 'form_reminder_sent', detail: f.phone } });
  }
}
return out;
